3	import {
4	  AuthProvider,
5	  OpenfortProvider,
6	  RecoveryMethod,
7	} from '@openfort/react';
8	import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi';
9	import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
10	import { useEffect, type ReactNode } from 'react';
11	import { base, baseSepolia } from 'viem/chains';
12	import { createConfig, WagmiProvider } from 'wagmi';
13	import { AuthSessionProvider } from '@/components/auth/auth-session-provider';
14	
15	const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
16	const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
17	const walletConnectProjectId =
18	  process.env.NEXT_PUBLIC_WALLET_CONNECT_PROJECT_ID || undefined;
19	const supportedChains = [base, baseSepolia] as const;
20	const defaultChainId =
21	  process.env.NEXT_PUBLIC_ENVIRONMENT === 'production'
22	    ? base.id
23	    : baseSepolia.id;
24	
25	const queryClient = new QueryClient();
26	const wagmiConfig = createConfig(
27	  getDefaultConfig({
28	    appName: 'InfraFund',
29	    chains: supportedChains,
30	    ssr: true,
31	    walletConnectProjectId,
32	  })
33	);
34	
35	// Called by the Openfort SDK when it needs to create or restore the Shield
36	// encryption session for this user's embedded wallet. Runs server-side (our
37	// Next.js API route) so SHIELD_SECRET_KEY is never exposed to the client.
38	// Openfort passes this token to the Shield service as proof that our backend
39	// has authorised the key-share operation.
40	async function getEncryptionSession({
41	  accessToken,
42	  otpCode,
43	  userId,
44	}: {
45	  accessToken: string;
46	  otpCode?: string;
47	  userId: string;
48	}) {
49	  const response = await fetch('/api/auth/encryption-session', {
50	    method: 'POST',
51	    headers: {
52	      Authorization: `Bearer ${accessToken}`,
53	      'Content-Type': 'application/json',
54	    },
55	    body: JSON.stringify({ otp_code: otpCode, user_id: userId }),
56	  });
57	  const data: unknown = await response.json().catch(() => null);
58	
59	  if (!response.ok) {
60	    const message =
61	      data && typeof data === 'object' && 'message' in data
62	        ? String(data.message)
63	        : 'Failed to create encryption session.';
64	    throw new Error(message);
65	  }
66	
67	  if (
68	    !data ||
69	    typeof data !== 'object' ||
70	    !('session' in data) ||
71	    typeof data.session !== 'string'
72	  ) {
73	    throw new Error('Invalid encryption session response.');
74	  }
75	
76	  return data.session;
77	}
78	
79	// Workaround for an Openfort SDK bug (openfort-xyz/openfort-js#275):
80	// EmbeddedWalletApi.createIframe() appends the hidden iframe to document.body
81	// without setting a referrerpolicy attribute. Openfort's edge (Cloudflare)
82	// enforces an origin allowlist check via the Referer request header, so when
83	// the browser sends the iframe navigation without a Referer — which happens
84	// when no referrer policy is explicitly set — the response is 403 and the
85	// wallet never becomes READY.
86	//
87	// We cannot use a MutationObserver (fires after appendChild as a microtask)
88	// or a document-level Referrer-Policy header / <meta name="referrer"> tag
89	// because Chrome commits the iframe navigation's referrer policy synchronously
90	// at the appendChild call site — any attribute set after appendChild is too late.
91	//
92	// Instead we patch Node.prototype.appendChild so our code runs synchronously
93	// BEFORE the real appendChild, allowing us to set referrerpolicy="origin" while
94	// the element is still detached. The patch is scoped to the component lifetime
95	// and is narrowly targeted: it only acts on <iframe id="openfort-iframe">.
96	function OpenfortIframeFix() {
97	  useEffect(() => {
98	    const original = Node.prototype.appendChild;
99	    Node.prototype.appendChild = function <T extends Node>(child: T): T {
100	      if (
101	        child instanceof HTMLIFrameElement &&
102	        child.id === 'openfort-iframe' &&
103	        !child.referrerPolicy
104	      ) {
105	        child.referrerPolicy = 'origin';
106	      }
107	      return original.call(this, child) as T;
108	    };
109	    return () => {
110	      Node.prototype.appendChild = original;
111	    };
112	  }, []);
113	  return null;
114	}
115	
