1	/**
2	 * Hook for controlling Openfort UI modal and navigation
3	 *
4	 * This hook provides programmatic control over the Openfort UI modal, including opening,
5	 * closing, and navigating between different screens. It handles route validation and
6	 * automatically selects appropriate screens based on user connection and authentication state.
7	 *
8	 * @returns UI control functions and modal state
9	 *
10	 * @example
11	 * ```tsx
12	 * const ui = useUI();
13	 *
14	 * if (ui.isOpen) {
15	 *   console.log('Openfort modal is open');
16	 * }
17	 *
18	 * ui.open(); // Opens modal with default route
19	 * ui.close(); // Closes modal
20	 * ui.openProfile(); // Opens user profile screen
21	 * ```
22	 */
23	export declare function useUI(): {
