395	  //      deferred until completeOnboarding() succeeds.
396	  const bootstrapSession = useCallback(async () => {
397	    if (!openfortUserId) {
398	      clearSession();
399	      setStatus('unauthenticated');
400	      return;
401	    }
402	
403	    setStatus('loading');
404	    setError(null);
405	
406	    // Provisional plan for the cookie-restore short-circuit. Once we know we
407	    // fell through to the Openfort exchange path we replace it.
408	    setStepPlan([
409	      'signing_in',
410	      'restoring_session',
411	      'loading_profile',
412	      'connecting_wallet',
413	    ]);
414	    completeStep('signing_in');
415	
416	    try {
417	      // Path 1: try to restore an existing app session via the refresh cookie.
418	      // This is the fast path for page reloads and returning sessions.
419	      startStep('restoring_session');
420	      const refreshedSession = await refreshBackendSession().catch(() => null);
421	
422	      if (refreshedSession) {
423	        try {
424	          completeStep('restoring_session');
425	          startStep('loading_profile');
426	          const me = await getBackendMe(refreshedSession.access_token);
427	          completeStep('loading_profile');
428	          // Route through createWalletIfNeeded (not finalizeAuthenticatedSession
429	          // directly) so the embedded-wallet iframe is loaded and the wallet
430	          // becomes usable for signing — even on session restore.
431	          await createWalletIfNeeded(refreshedSession.access_token, me);
432	          return;
433	        } catch {
434	          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
435	          // Clear the stale cookie and fall through to Openfort re-auth.
436	          await logoutBackendSession().catch(() => undefined);
437	        }
438	      }
439	
440	      // Paths 2 & 3: no valid refresh cookie; re-authenticate via Openfort token.
441	      // Replace the provisional plan with the longer one for this branch.
442	      setStepPlan([
443	        'signing_in',
444	        'checking_account',
445	        'restoring_session',
446	        'loading_profile',
447	        'connecting_wallet',
448	      ]);
449	      completeStep('signing_in');
450	
451	      startStep('checking_account');
452	      const openfortAccessToken = await getAccessToken();
453	
454	      if (!openfortAccessToken) {
455	        throw new Error('Openfort access token is unavailable.');
456	      }
457	
458	      const checkResponse = await checkOpenfortUser(openfortAccessToken);
459	      completeStep('checking_account');
460	
461	      if (!checkResponse.exists) {
462	        // Path 3: new user — hold the Openfort token and show the qualification
463	        // questionnaire. Wallet creation is deferred to completeOnboarding().
464	        // Hide the progress modal so the questionnaire is the only surface.
465	        closeOpenfortModal();
466	        setPendingOnboardingAccessToken(openfortAccessToken);
467	        hideProgress();
468	        setStatus('needs_onboarding');
469	        return;
470	      }
471	
472	      // Path 2: existing user — exchange the Openfort token for an app session.
473	      startStep('restoring_session');
474	      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
475	      completeStep('restoring_session');
476	
477	      startStep('loading_profile');
478	      const me = await getBackendMe(loginResponse.access_token);
479	      completeStep('loading_profile');
480	
481	      await createWalletIfNeeded(loginResponse.access_token, me);
482	    } catch (sessionError) {
483	      reportError(sessionError, {
484	        area: 'auth',
485	        tags: { stage: 'bootstrap' },
486	        extra: baseReportExtras(),
487	      });
488	      setBackendAccessToken(null);
489	      setBackendUser(null);
490	      setPendingOnboardingAccessToken(null);
491	      setPendingWalletCreation(null);
492	      const userMessage = commitUserFacingError(getErrorMessage(sessionError));
493	      // Mark the currently-active step as failed so the modal points at the
494	      // step that broke. If nothing is active (shouldn't happen), this no-ops.
495	      setAuthProgress((current) => {
496	        if (!current) return current;
497	        const activeStep = current.steps.find((s) => s.status === 'active');
498	        if (!activeStep) return current;
499	        const steps = current.steps.map((s) =>
500	          s.id === activeStep.id
501	            ? {
502	                ...s,
503	                status: 'error' as AuthStepStatus,
504	                errorMessage: userMessage,
505	              }
506	            : s
507	        );
508	        return { ...current, steps };
509	      });
510	      setStatus('error');
511	    }
512	  }, [
513	    baseReportExtras,
514	    clearSession,
515	    closeOpenfortModal,
516	    commitUserFacingError,
517	    completeStep,
518	    createWalletIfNeeded,
519	    getAccessToken,
520	    hideProgress,
521	    openfortUserId,
522	    setStepPlan,
523	    startStep,
