const createWalletIfNeeded = useCallback(
  async (accessToken: string, currentUser: BackendMeResponse) => {
    setBackendAccessToken(accessToken);
    setBackendUser(currentUser);
    setPendingWalletCreation({ accessToken, user: currentUser });
    setStatus('creating_wallet');

    // Returning users with an existing wallet are reconnecting, not
    // provisioning a wallet for the first time. The label difference matters
    // because new-user provisioning takes meaningfully longer (Shield key
    // share is being created, not restored).
    const walletStepId: AuthStepId =
      wallets.length > 0 ? 'connecting_wallet' : 'setting_up_wallet';

    startStep(walletStepId);

    try {
      await create({
        recoveryMethod: RecoveryMethod.AUTOMATIC,
      });
      completeStep(walletStepId);
      finalizeAuthenticatedSession(accessToken, currentUser);
    } catch (walletError) {
      const rawMessage = getErrorMessage(walletError);
      reportError(walletError, {
        area: 'wallet',
        tags: { stage: 'create' },
        extra: {
          ...baseReportExtras(),
          hasExistingWallet: wallets.length > 0,
        },
      });
      const userMessage = commitUserFacingError(rawMessage);
      failStep(walletStepId, userMessage);
      setStatus('error');
    }
  },
  [
    baseReportExtras,
    commitUserFacingError,
    completeStep,
    create,
    failStep,
    finalizeAuthenticatedSession,
    startStep,
    wallets.length,
  ]
);

