1	'use client';
2	
3	// AuthSessionProvider bridges Openfort identity with our app session.
4	//
5	// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
6	// session (JWT + httpOnly refresh cookie), user profile, and the qualification
7	// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
8	// we call create() explicitly at the right moment.
9	//
10	// Status machine:
11	//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
12	//                 ↘ creating_wallet → authenticated   (existing user)
13	//                 ↘ error                             (any failure)
14	//
15	// New-user path (registration):
16	//   Openfort auth → check backend (exists: false) → qualification questionnaire
17	//   → backend exchange with role/type → createWalletIfNeeded → authenticated
18	//
19	// Existing-user path (login):
20	//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
21	//                                        ↘ no cookie → check backend (exists: true)
22	//                                          → backend exchange → createWalletIfNeeded
23	//
24	// createWalletIfNeeded always calls Openfort's create() to load the iframe and
25	// establish the embedded-wallet connection. For new users create() provisions
26	// the wallet; for returning users it reconnects to the existing one. Skipping
27	// this step for returning users leaves the wallet in [Not connected] state
28	// because the embedded-wallet iframe is never loaded (connectOnLogin: false).
29	
30	import type { User } from '@openfort/openfort-js';
31	import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
32	import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
33	import {
34	  checkOpenfortUser,
35	  deleteBackendAccount,
36	  exchangeOpenfortSession,
37	  getBackendMe,
38	  logoutBackendSession,
39	  refreshBackendSession,
40	  type BackendMeResponse,
41	} from '@/lib/backend-auth-client';
42	import {
43	  QualificationQuestionnaire,
44	  type QualificationSubmission,
45	} from './qualification-questionnaire';
46	import {
47	  createContext,
48	  useCallback,
49	  useContext,
50	  useEffect,
51	  useMemo,
52	  useRef,
53	  useState,
54	  type ReactNode,
55	} from 'react';
56	import { usePathname } from 'next/navigation';
57	import { reportError } from '@/lib/error-reporting';
58	
59	type AppSessionStatus =
60	  | 'idle'
61	  | 'loading'
62	  | 'needs_onboarding'
63	  | 'creating_wallet'
64	  | 'authenticated'
65	  | 'unauthenticated'
66	  | 'error';
67	
68	type ErrorCategory = 'recoverable' | 'fatal';
69	
70	type AuthStepId =
71	  | 'signing_in'
72	  | 'checking_account'
73	  | 'restoring_session'
74	  | 'creating_account'
75	  | 'loading_profile'
76	  | 'connecting_wallet'
77	  | 'setting_up_wallet';
78	
79	type AuthStepStatus = 'pending' | 'active' | 'done' | 'error';
80	
81	export interface AuthProgressStep {
82	  id: AuthStepId;
83	  label: string;
84	  status: AuthStepStatus;
85	  errorMessage?: string;
86	}
87	
88	interface AuthProgress {
89	  steps: AuthProgressStep[];
90	  isVisible: boolean;
91	}
92	
93	const STEP_LABELS: Record<AuthStepId, string> = {
94	  signing_in: 'Authenticating with Openfort',
95	  checking_account: 'Checking your account',
96	  restoring_session: 'Restoring your session',
97	  creating_account: 'Creating your account',
98	  loading_profile: 'Loading your profile',
99	  connecting_wallet: 'Connecting your wallet',
100	  setting_up_wallet: 'Setting up your wallet',
101	};
102	
103	interface AuthSessionContextValue {
104	  status: AppSessionStatus;
105	  backendAccessToken: string | null;
106	  backendUser: BackendMeResponse | null;
107	  openfortUser: User | null;
108	  isOpenfortLoading: boolean;
109	  isOpenfortAuthenticated: boolean;
110	  error: string | null;
111	  errorCategory: ErrorCategory | null;
112	  retry: () => void;
113	  deleteAccount: () => Promise<void>;
114	  logout: () => Promise<void>;
115	  authProgress: AuthProgress | null;
116	  dismissProgress: () => void;
117	}
118	
119	const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
120	const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';
121	
122	function getErrorMessage(error: unknown) {
123	  if (error instanceof Error && error.message) {
124	    return error.message;
125	  }
126	
127	  return 'Failed to initialize your session.';
128	}
129	
130	function getUserFacingErrorMessage(message: string) {
131	  if (/failed to establish iFrame connection/i.test(message)) {
132	    return "We couldn't connect to the wallet service. Please check your connection and try again.";
133	  }
134	
135	  if (/not logged in|session/i.test(message)) {
136	    return 'Your session expired. Please sign in again.';
137	  }
138	
139	  if (/failed to fetch|networkerror/i.test(message)) {
140	    return 'We hit a network issue. Please try again.';
141	  }
142	
143	  return 'Something went wrong. Please try again.';
144	}
145	
146	function classifyError(message: string): ErrorCategory {
147	  if (
148	    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
149	      message
150	    )
151	  ) {
152	    return 'recoverable';
153	  }
154	
155	  return 'fatal';
156	}
157	
158	function clearOnboardingDraft() {
159	  if (typeof window !== 'undefined') {
160	    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
161	  }
162	}
163	
164	export function AuthSessionProvider({ children }: { children: ReactNode }) {
165	  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
166	  const { signOut } = useSignOut();
167	  const { close: closeOpenfortModal } = useUI();
168	  const { create, wallets } = useEthereumEmbeddedWallet();
169	  const openfortUserId = user?.id ?? null;
170	  const [status, setStatus] = useState<AppSessionStatus>('idle');
171	  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
172	    null
173	  );
174	  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
175	    null
176	  );
177	  const [error, setError] = useState<string | null>(null);
178	  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
179	    null
180	  );
181	  const [retryCount, setRetryCount] = useState(0);
182	  const pathname = usePathname();
183	  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
184	    useState<string | null>(null);
185	  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
186	    accessToken: string;
187	    user: BackendMeResponse;
188	    walletStepId: 'connecting_wallet' | 'setting_up_wallet';
189	  } | null>(null);
190	  const previousAuthState = useRef(false);
191	  // Deduplication key: we only run one bootstrap per (userId, retryCount) pair.
192	  // This prevents the useEffect from re-triggering bootstrap when callbacks are
193	  // recreated due to dependency changes mid-flow.
194	  const bootstrapAttemptKeyRef = useRef<string | null>(null);
195	  const [authProgress, setAuthProgress] = useState<AuthProgress | null>(null);
196	
197	  const setStepPlan = useCallback((stepIds: AuthStepId[]) => {
198	    setAuthProgress({
199	      isVisible: true,
200	      steps: stepIds.map((id) => ({
201	        id,
202	        label: STEP_LABELS[id],
203	        status: 'pending',
204	      })),
205	    });
206	  }, []);
207	
208	  const updateStep = useCallback(
209	    (id: AuthStepId, patch: Partial<AuthProgressStep>) => {
210	      setAuthProgress((current) => {
211	        if (!current) return current;
212	        const steps = current.steps.map((step) =>
213	          step.id === id ? { ...step, ...patch } : step
214	        );
215	        return { ...current, steps };
216	      });
217	    },
218	    []
219	  );
220	
221	  const startStep = useCallback(
222	    (id: AuthStepId) => {
223	      updateStep(id, { status: 'active', errorMessage: undefined });
224	    },
225	    [updateStep]
226	  );
227	
228	  const completeStep = useCallback(
229	    (id: AuthStepId) => {
230	      updateStep(id, { status: 'done', errorMessage: undefined });
231	    },
232	    [updateStep]
233	  );
234	
235	  const completeStepsThrough = useCallback((id: AuthStepId) => {
236	    setAuthProgress((current) => {
237	      if (!current) return current;
238	      let reached = false;
239	      const steps = current.steps.map((step) => {
240	        if (reached) return step;
241	        const next: AuthProgressStep = { ...step, status: 'done' };
242	        if (step.id === id) reached = true;
243	        return next;
244	      });
245	      return { ...current, steps };
246	    });
247	  }, []);
248	
249	  const failStep = useCallback(
250	    (id: AuthStepId, errorMessage: string) => {
251	      updateStep(id, { status: 'error', errorMessage });
252	    },
253	    [updateStep]
254	  );
255	
256	  const showProgress = useCallback(() => {
257	    setAuthProgress((current) =>
258	      current ? { ...current, isVisible: true } : current
259	    );
260	  }, []);
261	
262	  const hideProgress = useCallback(() => {
263	    setAuthProgress((current) =>
264	      current ? { ...current, isVisible: false } : current
265	    );
266	  }, []);
267	
268	  const clearProgress = useCallback(() => {
269	    setAuthProgress(null);
270	  }, []);
271	
272	  const dismissProgress = useCallback(() => {
273	    setAuthProgress(null);
274	  }, []);
275	
276	  const clearSession = useCallback(() => {
277	    setBackendAccessToken(null);
278	    setBackendUser(null);
279	    setPendingOnboardingAccessToken(null);
280	    setPendingWalletCreation(null);
281	    setError(null);
282	    setErrorCategory(null);
283	    bootstrapAttemptKeyRef.current = null;
284	    clearOnboardingDraft();
285	    clearProgress();
286	  }, [clearProgress]);
287	
288	  const commitUserFacingError = useCallback((raw: string) => {
289	    const userMessage = getUserFacingErrorMessage(raw);
290	    setError(userMessage);
291	    setErrorCategory(classifyError(raw));
292	    return userMessage;
293	  }, []);
294	
295	  const baseReportExtras = useCallback(
296	    () => ({
297	      route: pathname ?? null,
298	      retryCount,
299	      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
300	    }),
301	    [openfortUserId, pathname, retryCount]
302	  );
303	
304	  // Terminal success state: app session is fully established and the wallet
305	  // iframe is connected. Closes any Openfort modal still visible and resets
306	  // all transient state accumulated during the auth/onboarding flow.
307	  const finalizeAuthenticatedSession = useCallback(
308	    (accessToken: string, currentUser: BackendMeResponse) => {
309	      closeOpenfortModal();
310	      setBackendAccessToken(accessToken);
311	      setBackendUser(currentUser);
312	      setPendingOnboardingAccessToken(null);
313	      setPendingWalletCreation(null);
314	      setError(null);
315	      setErrorCategory(null);
316	      clearOnboardingDraft();
317	      setStatus('authenticated');
318	    },
319	    [closeOpenfortModal]
320	  );
321	
322	  // Loads the Openfort embedded-wallet iframe and connects/creates the wallet,
323	  // then transitions to authenticated.
324	  //
325	  // Context when called: the backend session is already established (accessToken
326	  // and currentUser are valid). The Openfort SDK is authenticated. The only
327	  // remaining step is to load the hidden iframe so the wallet is usable.
328	  //
329	  // Why always call create(): connectOnLogin: false means the SDK never loads
330	  // the iframe automatically. create() is the correct call for both paths:
331	  //   - New user:      provisions the wallet and connects it via the iframe.
332	  //   - Existing user: reconnects to the existing wallet via the iframe.
333	  //                    The SDK's wallets[] array may already contain the wallet
334	  //                    (fetched from the Openfort API), but that does not mean
335	  //                    the iframe is loaded — without it the wallet is [Not
336	  //                    connected] and cannot sign transactions. Skipping create()
337	  //                    when wallets.length > 0 was the original bug causing
338	  //                    returning users to see [Not connected] on every login.
339	  const createWalletIfNeeded = useCallback(
340	    async (
341	      accessToken: string,
342	      currentUser: BackendMeResponse,
343	      walletStepId: 'connecting_wallet' | 'setting_up_wallet'
344	    ) => {
345	      setBackendAccessToken(accessToken);
346	      setBackendUser(currentUser);
347	      setPendingWalletCreation({
348	        accessToken,
349	        user: currentUser,
350	        walletStepId,
351	      });
352	      setStatus('creating_wallet');
353	      // walletStepId is decided by the caller: 'connecting_wallet' for
354	      // returning users, 'setting_up_wallet' for new users post-questionnaire.
355	      // We can't decide here from wallets.length because the SDK's wallets[]
356	      // is populated asynchronously and may still be empty at this point even
357	      // for returning users.
358	      startStep(walletStepId);
359	
360	      try {
361	        await create({
362	          recoveryMethod: RecoveryMethod.AUTOMATIC,
363	        });
364	        completeStep(walletStepId);
365	        finalizeAuthenticatedSession(accessToken, currentUser);
366	      } catch (walletError) {
367	        const rawMessage = getErrorMessage(walletError);
368	        reportError(walletError, {
369	          area: 'wallet',
370	          tags: { stage: 'create' },
371	          extra: {
372	            ...baseReportExtras(),
373	            hasExistingWallet: wallets.length > 0,
374	          },
375	        });
376	        const userMessage = commitUserFacingError(rawMessage);
377	        failStep(walletStepId, userMessage);
378	        setStatus('error');
379	      }
380	    },
381	    [
382	      baseReportExtras,
383	      commitUserFacingError,
384	      completeStep,
385	      create,
386	      failStep,
387	      finalizeAuthenticatedSession,
388	      startStep,
389	      wallets.length,
390	    ]
391	  );
392	
393	  // Runs once per Openfort user identity (keyed on openfortUserId + retryCount).
394	  // Determines which path the user takes and drives them to createWalletIfNeeded.
395	  //
396	  // Priority order:
397	  //   1. Valid refresh cookie → restore the app session directly, skip Openfort
398	  //      token exchange (faster; avoids an extra round-trip to Openfort API).
399	  //   2. No refresh cookie, existing backend user → exchange Openfort token for
400	  //      app session.
401	  //   3. No backend user → show qualification questionnaire; wallet creation is
402	  //      deferred until completeOnboarding() succeeds.
403	  const bootstrapSession = useCallback(async () => {
404	    if (!openfortUserId) {
405	      clearSession();
406	      setStatus('unauthenticated');
407	      return;
408	    }
409	
410	    setStatus('loading');
411	    setError(null);
412	
413	    // Single fixed-length plan covering the union of both returning-user
414	    // sub-paths. The cookie short-circuit (Path 1) skips checking_account by
415	    // marking it 'done' alongside signing_in. The exchange path (Path 2) walks
416	    // through it normally. The list never grows or shrinks mid-flight.
417	    setStepPlan([
418	      'signing_in',
419	      'checking_account',
420	      'restoring_session',
421	      'loading_profile',
422	      'connecting_wallet',
423	    ]);
424	    completeStep('signing_in');
425	
426	    try {
427	      // Path 1: try to restore an existing app session via the refresh cookie.
428	      // This is the fast path for page reloads and returning sessions.
429	      // The cookie attempt is silent (no UI change) — typically resolves in
430	      // <50 ms. Showing a spinner for it would tick step 3 active before
431	      // step 2, which looks out-of-order.
432	      const refreshedSession = await refreshBackendSession().catch(() => null);
433	
434	      if (refreshedSession) {
435	        try {
436	          // Cookie path succeeded. Tick steps 2 and 3 in order: the cookie
437	          // makes both 'checking_account' (we know who you are) and
438	          // 'restoring_session' (your session is restored) effectively true.
439	          completeStep('checking_account');
440	          completeStep('restoring_session');
441	          startStep('loading_profile');
442	          const me = await getBackendMe(refreshedSession.access_token);
443	          completeStep('loading_profile');
444	          // Route through createWalletIfNeeded (not finalizeAuthenticatedSession
445	          // directly) so the embedded-wallet iframe is loaded and the wallet
446	          // becomes usable for signing — even on session restore.
447	          await createWalletIfNeeded(
448	            refreshedSession.access_token,
449	            me,
450	            'connecting_wallet'
451	          );
452	          return;
453	        } catch {
454	          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
455	          // Clear the stale cookie and fall through to Openfort re-auth. Reset
456	          // the steps we already ticked in the cookie branch so the exchange
457	          // path can re-walk them in order.
458	          await logoutBackendSession().catch(() => undefined);
459	          updateStep('checking_account', { status: 'pending' });
460	          updateStep('restoring_session', { status: 'pending' });
461	          updateStep('loading_profile', { status: 'pending' });
462	        }
463	      }
464	
465	      // Paths 2 & 3: no valid refresh cookie; re-authenticate via Openfort token.
466	      startStep('checking_account');
467	      const openfortAccessToken = await getAccessToken();
468	
469	      if (!openfortAccessToken) {
470	        throw new Error('Openfort access token is unavailable.');
471	      }
472	
473	      const checkResponse = await checkOpenfortUser(openfortAccessToken);
474	      completeStep('checking_account');
475	
476	      if (!checkResponse.exists) {
477	        // Path 3: new user — hold the Openfort token and show the qualification
478	        // questionnaire. Wallet creation is deferred to completeOnboarding().
479	        // Hide the progress modal so the questionnaire is the only surface.
480	        closeOpenfortModal();
481	        setPendingOnboardingAccessToken(openfortAccessToken);
482	        hideProgress();
483	        setStatus('needs_onboarding');
484	        return;
485	      }
486	
487	      // Path 2: existing user — exchange the Openfort token for an app session.
488	      startStep('restoring_session');
489	      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
490	      completeStep('restoring_session');
491	
492	      startStep('loading_profile');
493	      const me = await getBackendMe(loginResponse.access_token);
494	      completeStep('loading_profile');
495	
496	      await createWalletIfNeeded(
497	        loginResponse.access_token,
498	        me,
499	        'connecting_wallet'
500	      );
501	    } catch (sessionError) {
502	      reportError(sessionError, {
503	        area: 'auth',
504	        tags: { stage: 'bootstrap' },
505	        extra: baseReportExtras(),
506	      });
507	      setBackendAccessToken(null);
508	      setBackendUser(null);
509	      setPendingOnboardingAccessToken(null);
510	      setPendingWalletCreation(null);
511	      const userMessage = commitUserFacingError(getErrorMessage(sessionError));
512	      // Mark the currently-active step as failed so the modal points at the
513	      // step that broke. If nothing is active (shouldn't happen), this no-ops.
514	      setAuthProgress((current) => {
515	        if (!current) return current;
516	        const activeStep = current.steps.find((s) => s.status === 'active');
517	        if (!activeStep) return current;
518	        const steps = current.steps.map((s) =>
519	          s.id === activeStep.id
520	            ? {
521	                ...s,
522	                status: 'error' as AuthStepStatus,
523	                errorMessage: userMessage,
524	              }
525	            : s
526	        );
527	        return { ...current, steps };
528	      });
529	      setStatus('error');
530	    }
531	  }, [
532	    baseReportExtras,
533	    clearSession,
534	    closeOpenfortModal,
535	    commitUserFacingError,
536	    completeStep,
537	    createWalletIfNeeded,
538	    getAccessToken,
539	    hideProgress,
540	    openfortUserId,
541	    setStepPlan,
542	    startStep,
543	    updateStep,
544	  ]);
545	
546	  // Called when the user submits the qualification questionnaire.
547	  // Context: status === 'needs_onboarding', pendingOnboardingAccessToken is set.
548	  // The Openfort token is still valid; no app session exists yet.
549	  const completeOnboarding = useCallback(
550	    async ({ role, type, organizationName }: QualificationSubmission) => {
551	      if (!pendingOnboardingAccessToken) {
552	        setError('Openfort access token is unavailable.');
553	        setStatus('error');
554	        return;
555	      }
556	
557	      setStatus('loading');
558	      setError(null);
559	
560	      // New-user post-questionnaire plan. signing_in and checking_account were
561	      // already completed during bootstrapSession; mark them done up front and
562	      // bring the progress modal back into view.
563	      setStepPlan([
564	        'signing_in',
565	        'checking_account',
566	        'creating_account',
567	        'loading_profile',
568	        'setting_up_wallet',
569	      ]);
570	      completeStepsThrough('checking_account');
571	      showProgress();
572	
573	      try {
574	        startStep('creating_account');
575	        const loginResponse = await exchangeOpenfortSession(
576	          pendingOnboardingAccessToken,
577	          {
578	            role,
579	            type,
580	            organization_name:
581	              type === 'organization' ? organizationName?.trim() : undefined,
582	          }
583	        );
584	        completeStep('creating_account');
585	
586	        startStep('loading_profile');
587	        const me = await getBackendMe(loginResponse.access_token);
588	        completeStep('loading_profile');
589	
590	        await createWalletIfNeeded(
591	          loginResponse.access_token,
592	          me,
593	          'setting_up_wallet'
594	        );
595	      } catch (sessionError) {
596	        reportError(sessionError, {
597	          area: 'auth',
598	          tags: { stage: 'onboarding' },
599	          extra: baseReportExtras(),
600	        });
601	        const userMessage = commitUserFacingError(
602	          getErrorMessage(sessionError)
603	        );
604	        setAuthProgress((current) => {
605	          if (!current) return current;
606	          const activeStep = current.steps.find((s) => s.status === 'active');
607	          if (!activeStep) return current;
608	          const steps = current.steps.map((s) =>
609	            s.id === activeStep.id
610	              ? {
611	                  ...s,
612	                  status: 'error' as AuthStepStatus,
613	                  errorMessage: userMessage,
614	                }
615	              : s
616	          );
617	          return { ...current, steps };
618	        });
619	        setStatus('needs_onboarding');
620	      }
621	    },
622	    [
623	      baseReportExtras,
624	      commitUserFacingError,
625	      completeStep,
626	      completeStepsThrough,
627	      createWalletIfNeeded,
628	      pendingOnboardingAccessToken,
629	      setStepPlan,
630	      showProgress,
631	      startStep,
632	    ]
633	  );
634	
635	  const abandonOnboarding = useCallback(async () => {
636	    clearSession();
637	    setStatus('loading');
638	
639	    await Promise.allSettled([
640	      logoutBackendSession(),
641	      signOut().catch(() => undefined),
642	    ]);
643	
644	    clearSession();
645	    setStatus('unauthenticated');
646	  }, [clearSession, signOut]);
647	
648	  const logout = useCallback(async () => {
649	    setStatus('loading');
650	    setError(null);
651	
652	    await Promise.allSettled([
653	      logoutBackendSession().catch(() => undefined),
654	      signOut().catch(() => undefined),
655	    ]);
656	
657	    clearSession();
658	    setStatus('unauthenticated');
659	  }, [clearSession, signOut]);
660	
661	  const deleteAccount = useCallback(async () => {
662	    setStatus('loading');
663	    setError(null);
664	
665	    try {
666	      if (backendAccessToken) {
667	        await deleteBackendAccount(backendAccessToken);
668	      }
669	    } catch (deleteError) {
670	      reportError(deleteError, {
671	        area: 'auth',
672	        tags: { stage: 'delete-account' },
673	        extra: baseReportExtras(),
674	      });
675	      commitUserFacingError(getErrorMessage(deleteError));
676	      setStatus('authenticated');
677	      return;
678	    }
679	
680	    await Promise.allSettled([
681	      logoutBackendSession().catch(() => undefined),
682	      signOut().catch(() => undefined),
683	    ]);
684	
685	    clearSession();
686	    setStatus('unauthenticated');
687	  }, [
688	    backendAccessToken,
689	    baseReportExtras,
690	    clearSession,
691	    commitUserFacingError,
692	    signOut,
693	  ]);
694	
695	  const retry = useCallback(() => {
696	    if (pendingWalletCreation) {
697	      void createWalletIfNeeded(
698	        pendingWalletCreation.accessToken,
699	        pendingWalletCreation.user,
700	        pendingWalletCreation.walletStepId
701	      );
702	      return;
703	    }
704	
705	    setRetryCount((count) => count + 1);
706	  }, [createWalletIfNeeded, pendingWalletCreation]);
707	
708	  // OAuth callback pre-emptive cover: when Openfort's redirect-based OAuth
709	  // returns the user to our app at `/?openfortAuthProviderUI=…`, the SDK's
710	  // ConnectModal auto-detects those params and reopens itself to run
711	  // ConnectWithOAuth (which calls storeCredentials). That UI flashes for a
712	  // few hundred ms before our bootstrap useEffect can run and close the
713	  // Openfort modal. Seeding authProgress here makes the task-103 modal
714	  // (z-[10001]) appear immediately on page load and cover the Openfort
715	  // ConnectWithOAuth page underneath. The signing_in step gets re-marked
716	  // done when bootstrapSession runs and overwrites the plan.
717	  useEffect(() => {
718	    if (typeof window === 'undefined') return;
719	    if (!window.location.search.includes('openfortAuthProviderUI')) return;
720	    setStepPlan([
721	      'signing_in',
722	      'checking_account',
723	      'restoring_session',
724	      'loading_profile',
725	      'connecting_wallet',
726	    ]);
727	    startStep('signing_in');
728	    // Eagerly close the Openfort modal too — defensive, since the SDK reopens
729	    // it on URL detection. Our bootstrap useEffect would do this once
730	    // isAuthenticated flips, but doing it here closes the gap.
731	    closeOpenfortModal();
732	    // Mount-only.
733	    // eslint-disable-next-line react-hooks/exhaustive-deps
734	  }, []);
735	
736	  // Primary driver: react to Openfort auth state changes.
737	  // bootstrapAttemptKey deduplicate calls so we run bootstrap exactly once
738	  // per (user, retryCount) pair, even when the effect re-fires because a
739	  // callback was recreated due to dependency changes mid-flow.
740	  useEffect(() => {
741	    if (isLoading) {
742	      setStatus((currentStatus) =>
743	        currentStatus === 'authenticated' ||
744	        currentStatus === 'needs_onboarding'
745	          ? currentStatus
746	          : 'loading'
747	      );
748	      return;
749	    }
750	
751	    if (!isAuthenticated || !openfortUserId) {
752	      clearSession();
753	      setStatus('unauthenticated');
754	      return;
755	    }
756	
757	    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;
758	
759	    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
760	      return;
761	    }
762	
763	    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;
764	
765	    // Close the Openfort built-in modal immediately. Without this, the SDK's
766	    // CONNECTED page (the "Connected — Manage wallets" popup) stays visible
767	    // until finalizeAuthenticatedSession runs at the end of the bootstrap.
768	    closeOpenfortModal();
769	
770	    void bootstrapSession();
771	  }, [
772	    bootstrapSession,
773	    clearSession,
774	    closeOpenfortModal,
775	    isAuthenticated,
776	    isLoading,
777	    openfortUserId,
778	    retryCount,
779	  ]);
780	
781	  // Secondary driver: detect explicit sign-out. Openfort's own sign-out does
782	  // not call our logout endpoint, so we must revoke the app session cookie here.
783	  useEffect(() => {
784	    const signedOut =
785	      previousAuthState.current && !isLoading && !isAuthenticated;
786	
787	    previousAuthState.current = isAuthenticated;
788	
789	    if (!signedOut) {
790	      return;
791	    }
792	
793	    clearSession();
794	    setStatus('unauthenticated');
795	    void logoutBackendSession().catch(() => undefined);
796	  }, [clearSession, isAuthenticated, isLoading]);
797	
798	  const value = useMemo<AuthSessionContextValue>(
799	    () => ({
800	      status,
801	      backendAccessToken,
802	      backendUser,
803	      openfortUser: user,
804	      isOpenfortLoading: isLoading,
805	      isOpenfortAuthenticated: isAuthenticated,
806	      error,
807	      errorCategory,
808	      retry,
809	      deleteAccount,
810	      logout,
811	      authProgress,
812	      dismissProgress,
813	    }),
814	    [
815	      status,
816	      backendAccessToken,
817	      backendUser,
818	      user,
819	      isLoading,
820	      isAuthenticated,
821	      error,
822	      errorCategory,
823	      retry,
824	      deleteAccount,
825	      logout,
826	      authProgress,
827	      dismissProgress,
828	    ]
829	  );
830	
831	  return (
832	    <AuthSessionContext.Provider value={value}>
833	      {children}
834	      <QualificationQuestionnaire
835	        isOpen={status === 'needs_onboarding'}
836	        openfortUser={user}
837	        submitError={error}
838	        isSubmitting={status === 'loading'}
839	        onClose={() => {
840	          void abandonOnboarding();
841	        }}
842	        onSubmit={completeOnboarding}
843	        onDisqualifiedSuccess={abandonOnboarding}
844	      />
845	    </AuthSessionContext.Provider>
846	  );
847	}
848	
849	export function useAuthSession() {
850	  const context = useContext(AuthSessionContext);
851	
852	  if (!context) {
853	    throw new Error(
854	      'useAuthSession must be used within an AuthSessionProvider.'
855	    );
856	  }
857	
858	  return context;
859	}
